{
  "question_material": [
    {
      "question_id": "Q01",
      "examples": [
        {
          "attribution": "Li et al. (2019) / CheckMate 025 队列分析",
          "use_in_review": "提供人类实体瘤患者血浆中肌苷浓度与ICI疗效的相关性数据，特别是生存期差异。",
          "finding": "在肾细胞癌（RCC）患者队列（CheckMate 025试验，Nivolumab治疗组 n=394, Everolimus对照组 n=349）中，通过非靶向代谢组学分析发现，只有肌苷水平与免疫检查点阻断（ICB）的总生存期（OS）显著相关。具体而言，基线血浆肌苷水平较高的Nivolumab治疗患者中位OS为33个月，而低肌苷水平患者的中位OS为22个月。这种关联仅在Nivolumab（抗PD-1）治疗组中存在，而在Everolimus（mTOR抑制剂）治疗组中未观察到显著差异。",
          "conditions": "人群：接受Nivolumab或Everolimus治疗的晚期肾细胞癌患者；分组依据：基线血浆肌苷水平的中位数分为高/低两组；指标：总生存期（OS）。",
          "reference_ids": [
            "R15"
          ]
        },
        {
          "attribution": "本研究 (Inhibition of UBA6 by inosine...)",
          "use_in_review": "补充说明肌苷在动物模型中的变化趋势及临床样本中UBA6表达与疗效的关系，作为肌苷-UBA6轴的临床相关性佐证。",
          "finding": "在小鼠模型中，携带B16-F0肿瘤的野生型小鼠血浆肌苷水平高于无肿瘤小鼠，但在接受ICI（抗PD-1 + 抗CTLA-4）治疗后，血浆肌苷水平下降。在人类临床验证部分，研究纳入了22名接受抗PD-1治疗的不同实体瘤（食管癌、肺癌、胃癌、结肠癌等）患者，发现部分缓解（PR）或疾病稳定（SD）患者的肿瘤组织中UBA6蛋白表达水平显著低于疾病进展（PD）患者。低UBA6表达组的总体响应率（ORR）为50%，高UBA6表达组为17%。虽然本研究未直接报告这22例患者血浆肌苷的具体浓度范围，但证实了UBA6低表达（模拟肌苷抑制效果）与良好ICI疗效正相关。",
          "conditions": "动物模型：B16-F0黑色素瘤小鼠，ICI治疗前后对比；临床队列：22名接受Sintilimab（抗PD-1）治疗的实体瘤患者，基于肿瘤组织UBA6蛋白表达（IHC评分）分组；指标：肿瘤体积、生存率、总体响应率（ORR）、UBA6蛋白表达水平。",
          "reference_ids": []
        }
      ],
      "explanation": "该研究通过代谢组学筛选和临床队列分析，确立了血浆肌苷水平与免疫检查点阻断（ICI）疗效的正相关性。机制上，肌苷并非仅作为能量来源或作用于免疫细胞，而是直接进入肿瘤细胞，抑制泛素激活酶UBA6的活性。UBA6的抑制导致肿瘤细胞内FAT10依赖的抗原加工和炎症信号通路改变，上调MHC-I类分子表达和干扰素反应基因，从而增强肿瘤内在免疫原性，使其对T细胞介导的细胞毒性更敏感。在临床上，肿瘤细胞中UBA6的高表达预测了较差的ICI疗效，而低UBA6表达则与更好的生存期和响应率相关，提示肌苷或其类似物可能通过靶向UBA6来克服ICI耐药。",
      "remaining_points": [
        "原文指出由于腺苷在体内半衰期极短（约10秒），而肌苷较长（约15小时），且样本缺失，本研究未在临床队列中直接测量血浆肌苷浓度，因此缺乏人类实体瘤患者血浆肌苷的具体浓度数值范围数据。",
        "临床验证队列样本量较小（n=22），限制了统计效力。"
      ]
    }
  ]
}
